def inside(p,poly):
    x,y=p; signs=[]
    for (x1,y1),(x2,y2) in zip(poly,poly[1:]+poly[:1]):
        cross=(x2-x1)*(y-y1)-(y2-y1)*(x-x1)
        if cross: signs.append(cross>0)
    return not signs or all(s==signs[0] for s in signs)
